    const store = new InMemorySessionStore();
    store.create('zeta', 'u1');
    store.create('alpha', 'u1');

    expect({listed: store.listFor('u1').map(row => row.sessionId), latest: store.latestFor('u1')?.sessionId}).toEqual({
