  ];
  for (const [sessionId, userId, day] of conversations) {
    store.create(sessionId, userId).entries.push({role: 'user', content: 'hello', timestamp: `${day}T00:00:00.000Z`});
  }
};

const startEngine = async (store: InMemorySessionStore, extra: object = {}): Promise<string> => {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    sessionStore: store,
    orchestrator: answeringOrchestrator,
    ...extra,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
};

// Collects every frame the server sends, and resolves once the connected frame has arrived.
const connect = async (url: string): Promise<{client: WebSocket; frames: Frame[]}> => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  const frames: Frame[] = [];
  client.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  await settle(frames, frame => frame.type === 'connected');
  return {client, frames};
};

// Resolves once a frame satisfies `done`, or the wait runs out, so a silent server fails an assertion rather than hanging.
const settle = (frames: Frame[], done: (frame: Frame) => boolean, waitMs = 2000): Promise<void> =>
  new Promise(resolve => {
    const started = Date.now();
    const poll = (): void => {
      if (frames.some(done) || Date.now() - started > waitMs) resolve();
      else setTimeout(poll, 10);
    };
    poll();
  });

// Sends one request, then a ping. The request's answer is awaited before the ping, so the pong proves nothing else followed it.
const ask = async (client: WebSocket, frames: Frame[], request: object): Promise<Frame[]> => {
  client.send(JSON.stringify(request));
  await settle(frames, frame => frame.type === 'conversation_list' || frame.type === 'error');
  client.send(JSON.stringify({type: 'ping', timestamp: 1}));
  await settle(frames, frame => frame.type === 'pong');
  return frames.filter(frame => frame.type !== 'connected');
};

// The connection's own conversation is listed like any other, holding no entries; its activity is the moment it was created, before the 2030 stamps.
const ownListing = (ownId: string): Array<Record<string, unknown>> => [
  {
    sessionId: 'newest',
    createdAt: expect.stringMatching(ISO_UTC),
    updatedAt: '2030-01-03T00:00:00.000Z',
    entryCount: 1,
  },
  {
    sessionId: 'middle',
    createdAt: expect.stringMatching(ISO_UTC),
    updatedAt: '2030-01-02T00:00:00.000Z',
    entryCount: 1,
  },
  {sessionId: 'older', createdAt: expect.stringMatching(ISO_UTC), updatedAt: '2030-01-01T00:00:00.000Z', entryCount: 1},
];

const ownIdOf = (frames: Frame[]): string => frames.find(frame => frame.type === 'connected')?.sessionId ?? '';

describe('the conversation list over the websocket', () => {
  it('answers list_conversations with one conversation_list of the user’s conversations, newest first, with ISO times and no stream_end', async () => {
    const store = new InMemorySessionStore();
    seed(store);
    const url = await startEngine(store, HISTORY_ON);
    const {client, frames} = await connect(url);

    const answer = await ask(client, frames, {type: 'list_conversations'});

    expect(answer.map(frame => frame.type)).toEqual(['conversation_list', 'pong']);
    expect(answer[0].conversations).toEqual(ownListing(ownIdOf(frames)));
  });

  it('answers a frame carrying another user’s id with the connecting user’s own list, never the id it names', async () => {
    const store = new InMemorySessionStore();
    seed(store);
    const url = await startEngine(store, HISTORY_ON);
    const {client, frames} = await connect(url);

    const answer = await ask(client, frames, {type: 'list_conversations', userId: 'u2'});

    expect(answer.map(frame => frame.type)).toEqual(['conversation_list', 'pong']);
    expect(answer[0].conversations).toEqual(ownListing(ownIdOf(frames)));
  });

  it('answers list_conversations with an UNSUPPORTED error and no list while history is not enabled', async () => {
    const store = new InMemorySessionStore();
    seed(store);
    const url = await startEngine(store);
    const {client, frames} = await connect(url);

    const answer = await ask(client, frames, {type: 'list_conversations'});

    expect(answer.map(frame => ({type: frame.type, code: frame.code}))).toEqual([
      {type: 'error', code: 'UNSUPPORTED'},
      {type: 'pong'},
    ]);
  });

  it('accepts a list_conversations frame with a limit of 1 to 200 or a parseable before, and refuses any other limit or before by naming the field', () => {
    const accepted = [
      {type: 'list_conversations'},
      {type: 'list_conversations', limit: 1},
      {type: 'list_conversations', limit: 200},
      {type: 'list_conversations', before: '2030-01-01T00:00:00.000Z'},
    ];
    const refused: Array<[object, string]> = [
      [{type: 'list_conversations', limit: 0}, 'limit'],
      [{type: 'list_conversations', limit: 201}, 'limit'],
      [{type: 'list_conversations', limit: 1.5}, 'limit'],
      [{type: 'list_conversations', limit: '10'}, 'limit'],
      [{type: 'list_conversations', before: 'not a date'}, 'before'],
    ];

    for (const message of accepted) expect(validateMessage(message)).toMatchObject({valid: true});
    for (const [message, field] of refused) {
      expect(validateMessage(message)).toEqual({valid: false, error: expect.stringContaining(field)});
    }
  });
});
